mapper.select:
SELECT t.id, t.yard_task_no, t.task_type, t.warehouse_id,
       t.source_order_type, t.source_order_id, t.source_order_no,
       t.container_no, t.container_resource_id, t.trailer_resource_id,
       t.wms_ready_status, t.wms_ready_time, t.appointment_id,
       t.dock_assign_time, t.call_time, t.priority,
       t.truck_no, t.driver_name, t.driver_phone,
       t.eta_yard_time, t.gate_in_time, t.dock_start_time, t.dock_finish_time,
       t.release_time, t.gate_out_time,
       t.dock_id, t.dock_code,
       t.operation_task_id, t.operation_status, t.operation_progress,
       t.operation_start_time, t.operation_finish_time, t.estimated_finish_time,
       t.loaded_qty, t.total_qty, t.loaded_pallet_qty, t.total_pallet_qty,
       t.yard_status,
       it.id AS open_internal_task_id,
       it.task_no AS open_internal_task_no,
       it.internal_task_type AS open_internal_task_type,
       it.task_status AS open_internal_task_status,
       COALESCE(it.to_dock_code, it.to_position_code) AS open_internal_task_target_code,
       t.visit_no, t.unload_round_no,
       t.is_reentry, t.reentry_reason, t.parent_task_id,
       t.exception_flag, t.exception_reason, t.source, t.remark,
       t.create_time
FROM yms_yard_task t
LEFT JOIN yms_internal_task it ON it.id = (
    SELECT x.id
    FROM yms_internal_task x
    WHERE x.deleted = 0
      AND x.parent_yard_task_id = t.id
      AND x.task_status NOT IN ('COMPLETED', 'FAILED', 'CANCELLED')
    ORDER BY x.create_time DESC
    LIMIT 1
)
WHERE t.deleted = 0

      AND t.warehouse_id = #{bo.warehouseId}



          AND t.task_type = #{bo.taskType}




                  AND t.task_type = 'DEVANNING'


                  AND t.task_type IN ('DELIVERY_LOADING','TRANSFER_LOADING','PICKUP_LOADING','RETURN_LOADING')





      AND FIND_IN_SET(t.yard_status, #{bo.yardStatus})


      AND (t.yard_task_no LIKE CONCAT('%', #{bo.keyword}, '%')
        OR t.source_order_no LIKE CONCAT('%', #{bo.keyword}, '%')
        OR t.container_no LIKE CONCAT('%', #{bo.keyword}, '%')
        OR t.truck_no LIKE CONCAT('%', #{bo.keyword}, '%')
        OR t.driver_name LIKE CONCAT('%', #{bo.keyword}, '%'))


      AND t.container_no LIKE CONCAT('%', #{bo.containerNo}, '%')


      AND t.truck_no LIKE CONCAT('%', #{bo.truckNo}, '%')


      AND t.source_order_no LIKE CONCAT('%', #{bo.sourceOrderNo}, '%')


      AND t.gate_in_time >= #{bo.beginGateInTime}


      AND t.gate_in_time <= #{bo.endGateInTime}




              AND t.eta_yard_time >= #{bo.beginTime}
              AND t.eta_yard_time <= #{bo.endTime}


              AND t.gate_in_time >= #{bo.beginTime}
              AND t.gate_in_time <= #{bo.endTime}


              AND t.dock_start_time >= #{bo.beginTime}
              AND t.dock_start_time <= #{bo.endTime}


              AND t.dock_finish_time >= #{bo.beginTime}
              AND t.dock_finish_time <= #{bo.endTime}


              AND t.release_time >= #{bo.beginTime}
              AND t.release_time <= #{bo.endTime}


              AND t.gate_out_time >= #{bo.beginTime}
              AND t.gate_out_time <= #{bo.endTime}


              AND t.create_time >= #{bo.beginTime}
              AND t.create_time <= #{bo.endTime}



ORDER BY t.gate_in_time DESC, t.create_time DESC
